/// A spring's position (0 -> 1) at `t_ms`, unit mass, from rest.
pub fn spring_at(damping: f32, stiffness: f32, t_ms: f32) -> f32 {
    let (mut x, mut v, c) = (0.0f32, 0.0f32, 2.0 * damping * stiffness.sqrt());
    let steps = t_ms.max(0.0) as u32;
    for _ in 0..steps { let a = -stiffness * (x - 1.0) - c * v; v += a / 1000.0; x += v / 1000.0; }
    x
}
